/* src/host/elf_image_test.c — T1 host golden test for the GB-013 ELF parser.
 *
 * Same source as the kernel links (src/kernel/elf_image.c): the gate that decides
 * whether a Linux binary may be loaded is proven on the host, before QEMU.
 *
 * Fixtures: the .elf files under tests/fixtures/elf/, generated by
 * tools/linux-abi/gen_test_elf.py (one valid image + one vector per rejection
 * class).  Override the directory with ELF_FIXTURE_DIR; optionally parse a real
 * static binary with ELF_REAL_BINARY=/path/to/static-binary.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "elf_image.h"

static int failures = 0;
static int checks = 0;

#define CHECK(cond, name) do {                                    \
    checks++;                                                     \
    if (cond) { printf("  PASS %s\n", name); }                    \
    else { printf("  FAIL %s\n", name); failures++; }             \
  } while (0)

#define CHECK_EQ(got, want, name) do {                            \
    checks++;                                                     \
    long long g_ = (long long)(got), w_ = (long long)(want);      \
    if (g_ == w_) { printf("  PASS %s\n", name); }                \
    else { printf("  FAIL %s (got %lld want %lld)\n", name, g_, w_); failures++; } \
  } while (0)

static const char *fdir(void) {
  const char *d = getenv("ELF_FIXTURE_DIR");
  return (d && *d) ? d : "tests/fixtures/elf";
}

/* Read a whole fixture; returns malloc'd buffer, sets *len.  NULL on failure. */
static uint8_t *slurp(const char *name, uint64_t *len) {
  char path[1024];
  snprintf(path, sizeof path, "%s/%s.elf", fdir(), name);
  FILE *f = fopen(path, "rb");
  if (!f) return NULL;
  fseek(f, 0, SEEK_END);
  long n = ftell(f);
  fseek(f, 0, SEEK_SET);
  if (n < 0) { fclose(f); return NULL; }
  uint8_t *buf = (uint8_t *)malloc((size_t)n + 1);
  if (!buf) { fclose(f); return NULL; }
  size_t got = fread(buf, 1, (size_t)n, f);
  fclose(f);
  *len = got;
  return buf;
}

static int expect(const char *name, int want) {
  uint64_t len = 0;
  uint8_t *buf = slurp(name, &len);
  if (!buf) {
    printf("  FAIL %s: fixture missing (run tools/linux-abi/gen_test_elf.py)\n", name);
    failures++; checks++;
    return 1;
  }
  struct elf_image img;
  memset(&img, 0, sizeof img);
  int rc = elf_parse(buf, len, &img);
  checks++;
  if (rc == want) {
    printf("  PASS %-26s -> %s\n", name, elf_strerror(rc));
  } else {
    printf("  FAIL %-26s -> %s (want %s)\n", name, elf_strerror(rc), elf_strerror(want));
    failures++;
  }
  free(buf);
  return 0;
}

int main(void) {
  printf("=== ELF image parser (GB-013) host tests ===\n");

  /* --- argument hygiene ------------------------------------------------- */
  struct elf_image img;
  CHECK_EQ(elf_parse(NULL, 0, &img), ELF_ERR_ARGS, "elf_parse(NULL) -> ARGS");
  CHECK_EQ(elf_parse("x", 1, NULL), ELF_ERR_ARGS, "elf_parse(img=NULL) -> ARGS");

  /* truncated buffers must never read past the end (ASAN-clean by design) */
  uint64_t vlen = 0;
  uint8_t *v = slurp("valid-x86_64-exec", &vlen);
  if (v) {
    struct elf_image t;
    CHECK_EQ(elf_parse(v, 8, &t), ELF_ERR_HDR_SHORT, "8-byte buffer -> HDR_SHORT");
    CHECK_EQ(elf_parse(v, 64, &t), ELF_ERR_PHOFF, "64-byte buffer -> PHOFF (no phdr table)");
    for (uint64_t n = 1; n <= 64; n++) {
      struct elf_image tmp;
      int rc = elf_parse(v, n, &tmp);
      if (rc == ELF_OK) { printf("  FAIL %llu-byte prefix parsed as OK\n", (unsigned long long)n); failures++; break; }
    }
    checks++;
    printf("  PASS every prefix of a valid image is rejected (no OOB read)\n");
    free(v);
  }

  /* --- the accept class ------------------------------------------------- */
  uint64_t len = 0;
  uint8_t *buf = slurp("valid-x86_64-exec", &len);
  if (!buf) {
    printf("FATAL: tests/fixtures/elf missing — run tools/linux-abi/gen_test_elf.py\n");
    return 1;
  }
  memset(&img, 0, sizeof img);
  CHECK_EQ(elf_parse(buf, len, &img), ELF_OK, "valid-x86_64-exec parses");
  CHECK_EQ(img.nsegs, 2, "two PT_LOAD segments");
  CHECK_EQ(img.phnum, 2, "phnum preserved");
  CHECK_EQ(img.entry, 0x401000ULL, "e_entry == 0x401000");
  CHECK_EQ(img.vaddr_base, 0x401000ULL, "vaddr_base page-aligned to 0x401000");
  CHECK_EQ(img.vaddr_end, 0x403000ULL, "vaddr_end covers the last segment");
  CHECK_EQ(elf_image_span(&img), 0x2000ULL, "span == 0x2000");
  CHECK_EQ(elf_page_down(0x401fff), 0x401000ULL, "elf_page_down");
  CHECK_EQ(elf_page_up(0x401001), 0x402000ULL, "elf_page_up");
  CHECK_EQ(img.segs[0].flags, ELF_PF_R | ELF_PF_X, "segment 0 is R+X");
  CHECK_EQ(img.segs[1].flags, ELF_PF_R | ELF_PF_W, "segment 1 is R+W");
  CHECK_EQ(img.is_pie, 0, "ET_EXEC flagged not-PIE");
  CHECK_EQ(img.needs_low_window, 1,
           "ET_EXEC at 0x400000 flagged needs_low_window (unmappable under the v2 window)");

  /* copy_into must place bytes at vaddr_base-relative offsets, zero the bss */
  {
    uint64_t span = elf_image_span(&img);
    uint8_t *dst = (uint8_t *)malloc((size_t)span);
    memset(dst, 0xEE, (size_t)span); /* poison: any untouched byte stays 0xEE */
    CHECK_EQ(elf_copy_into(&img, buf, len, dst, span), ELF_OK, "elf_copy_into succeeds");
    CHECK_EQ(dst[0], 0x90, "seg0 first byte copied to vaddr_base");
    CHECK_EQ(dst[0x1f], 0x90, "seg0 last byte copied");
    CHECK_EQ(dst[0x1000], 0x00, "seg1 first byte copied (0x00 fill)");
    CHECK_EQ(dst[0x1010], 0x00, "seg1 bss tail zeroed (filesz=0x10 memsz=0x30)");
    CHECK_EQ(dst[0x102f], 0x00, "seg1 last memsz byte zeroed");
    CHECK_EQ(dst[0x20], 0xEE, "inter-segment hole left untouched (caller pre-zeroes)");
    CHECK_EQ(dst[span - 1], 0xEE, "page hole after the last segment untouched");
    CHECK_EQ(elf_copy_into(&img, buf, len, dst, 0x10), ELF_ERR_DST_RANGE, "short dst -> DST_RANGE");
    free(dst);
  }
  free(buf);

  /* bss: filesz < memsz -> the tail must be zeroed by copy_into */
  {
    uint64_t l2 = 0;
    uint8_t *b2 = slurp("valid-exec-bss", &l2);
    if (b2) {
      struct elf_image i2;
      CHECK_EQ(elf_parse(b2, l2, &i2), ELF_OK, "valid-exec-bss parses");
      CHECK_EQ(i2.segs[0].filesz < i2.segs[0].memsz, 1, "filesz < memsz recorded");
      uint64_t span = elf_image_span(&i2);
      uint8_t *dst = (uint8_t *)malloc((size_t)span);
      memset(dst, 0xEE, (size_t)span);
      CHECK_EQ(elf_copy_into(&i2, b2, l2, dst, span), ELF_OK, "bss copy_into succeeds");
      CHECK_EQ(dst[0x1f], 0x90, "bss: file bytes present");
      CHECK_EQ(dst[0x20], 0x00, "bss: tail zeroed");
      CHECK_EQ(dst[0x3f], 0x00, "bss: last memsz byte zeroed");
      free(dst);
      free(b2);
    }
  }

  /* three-segment image: every segment lands where the plan says */
  {
    uint64_t l3 = 0;
    uint8_t *b3 = slurp("tour-exec-3seg", &l3);
    if (b3) {
      struct elf_image i3;
      CHECK_EQ(elf_parse(b3, l3, &i3), ELF_OK, "tour-exec-3seg parses");
      CHECK_EQ(i3.nsegs, 3, "three PT_LOAD segments");
      uint64_t span = elf_image_span(&i3);
      CHECK_EQ(span, 0x3000ULL, "span covers all three pages");
      uint8_t *dst = (uint8_t *)malloc((size_t)span);
      memset(dst, 0xEE, (size_t)span);
      CHECK_EQ(elf_copy_into(&i3, b3, l3, dst, span), ELF_OK, "3-seg copy_into succeeds");
      CHECK_EQ(dst[0x0000], 0x90, "seg0 @0x0");
      CHECK_EQ(dst[0x1000], 0xAB, "seg1 @0x1000");
      CHECK_EQ(dst[0x2000], 0x00, "seg2 @0x2000 (zero fill)");
      CHECK_EQ(dst[0x2080], 0x00, "seg2 bss tail zeroed");
      free(dst);
      free(b3);
    }
  }

  /* --- the reject classes (one vector each) ----------------------------- */
  /* the accept class also covers static PIE, and ET_EXEC's window flag */
  {
    uint64_t lp = 0;
    uint8_t *bp = slurp("valid-static-pie", &lp);
    if (bp) {
      struct elf_image ip;
      CHECK_EQ(elf_parse(bp, lp, &ip), ELF_OK, "valid-static-pie (ET_DYN, no PT_INTERP) parses");
      CHECK_EQ(ip.is_pie, 1, "static PIE flagged is_pie");
      CHECK_EQ(ip.needs_low_window, 0, "static PIE needs no low window");
      free(bp);
    }
  }
  expect("reject-bad-magic", ELF_ERR_MAGIC);
  expect("reject-class32", ELF_ERR_CLASS);
  expect("reject-bigendian", ELF_ERR_ENDIAN);
  expect("reject-arm-machine", ELF_ERR_MACHINE);
  expect("reject-dyn-interp", ELF_ERR_INTERP);
  expect("reject-truncated", ELF_ERR_SEG_RANGE);
  expect("reject-phoff-oob", ELF_ERR_PHOFF);
  expect("reject-phnum-zero", ELF_ERR_NO_LOAD);
  expect("reject-interp", ELF_ERR_INTERP);
  expect("reject-nonload-only", ELF_ERR_NO_LOAD);
  expect("reject-filesz-gt-memsz", ELF_ERR_SEG_MEMSZ);
  expect("reject-overlap", ELF_ERR_SEG_OVERLAP);
  expect("reject-bad-entry", ELF_ERR_ENTRY);
  expect("reject-no-exec", ELF_ERR_NO_TEXT);

  /* --- optional: a real static x86_64 binary ---------------------------- */
  {
    const char *real = getenv("ELF_REAL_BINARY");
    if (real && *real) {
      FILE *f = fopen(real, "rb");
      if (f) {
        fseek(f, 0, SEEK_END);
        long n = ftell(f);
        fseek(f, 0, SEEK_SET);
        uint8_t *rb = (uint8_t *)malloc((size_t)n);
        size_t got = fread(rb, 1, (size_t)n, f);
        fclose(f);
        struct elf_image ri;
        int rc = elf_parse(rb, got, &ri);
        checks++;
        /* Three correct answers for a real binary: OK (static ET_EXEC — the W0
         * target), INTERP (dynamic ET_EXEC, needs ld.so), TYPE (ET_DYN/PIE).
         * Anything else means the parser misclassified a real program. */
        if (rc == ELF_OK || rc == ELF_ERR_INTERP || rc == ELF_ERR_TYPE) {
          printf("  PASS real binary %s -> %s (entry 0x%llx, %u segs)\n", real, elf_strerror(rc),
                 (unsigned long long)ri.entry, ri.nsegs);
        } else {
          printf("  FAIL real binary %s -> %s\n", real, elf_strerror(rc));
          failures++;
        }
        free(rb);
      }
    } else {
      printf("  SKIP real-binary parse (set ELF_REAL_BINARY=/path/to/static-x86_64)\n");
    }
  }

  printf("=== %d checks, %d failed ===\n", checks, failures);
  if (failures == 0) {
    printf("ALL ELF IMAGE HOST TESTS PASSED\n");
    return 0;
  }
  printf("ELF IMAGE HOST TESTS FAILED (%d)\n", failures);
  return 1;
}
